use vstd::prelude::*;

verus! {

fn polymulx(c: Vec<f32>) -> (result: Vec<f32>)
    ensures
        // The result is exactly one longer than the input
        result.len() == c.len() + 1,
    ensures
        // The first element of result is 0.0
        result.index(0) == 0.0,
    ensures
        // For every input index i, the (i+1)-th of result equals c[i]
        forall|i: usize|  i < c.len() ==> result.index(i + 1) == c.index(i),
{
    // Allocate a new vector with capacity for c.len() + 1 elements
    let mut res: Vec<f32> = Vec::with_capacity(c.len() + 1);
    // Push the leading 0.0
    res.push(0.0);

    // i = number of elements from c that have been copied so far
    let mut i: usize = 0;
    // Loop invariant:
    //   0 <= i <= c.len()
    //   res.len() == i + 1             (we have pushed exactly i elements from c, plus the initial 0.0)
    //   res[0] == 0.0
    //   for all k < i, res[k+1] == c[k]
    while i < c.len()
        invariant
            i <= c.len(),
            res.len() == i + 1,
            res.index(0) == 0.0,
            forall|k: usize| k < i ==> res.index(k + 1) == c.index(k),
        decreases
            c.len() - i,
    {
        // Copy c[i] into res
        let x: f32 = c.index(i);
        res.push(x);
        i = i + 1;
    }

    // At the end of the loop, i == c.len(), so res.len() == c.len() + 1
    res
}

} // verus!

